const input = $('Input de prueba').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.Session_ID);
const m = rows[0] ?? {};
return [{ json: {
  ...input,
  memoria_existe: Boolean(m.Session_ID),
  user_name: m.user_name || '',
  estado_caso: m.Estado_Caso || '',
  last_summary: m.Resumen_Consolidado || '',
  datos_clave: m.Datos_Clave || '',
  contador_mensajes: Number(m.contador_mensajes || 0)
} }];

const ctx = $('Armar contexto compartido').first().json;
const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  d = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/```$/, '').trim());
} catch (e) {
  d = { intent: 'UNKNOWN', confidence: 0, risk: 'HIGH', nombre_usuario: null };
}
const allowed = ['BILLING', 'TECH_SUPPORT', 'SALES', 'UNKNOWN'];
const nombre = typeof d.nombre_usuario === 'string' && d.nombre_usuario.trim() ? d.nombre_usuario.trim() : null;
return [{ json: {
  original_input: ctx.original_input,
  session_id: ctx.session_id,
  user_name: nombre ?? ctx.user_name,
  estado_caso: ctx.estado_caso,
  last_summary: ctx.last_summary,
  datos_clave: ctx.datos_clave,
  historial_reciente: ctx.historial_reciente,
  contador_mensajes: Number(ctx.contador_mensajes || 0),
  memoria_existe: ctx.memoria_existe,
  intent: allowed.includes(d.intent) ? d.intent : 'UNKNOWN',
  confidence: Math.max(0, Math.min(1, Number(d.confidence ?? 0))),
  risk: ['LOW', 'MEDIUM', 'HIGH'].includes(d.risk) ? d.risk : 'HIGH',
  es_saludo: d.es_saludo === true
} }];

const src = $('Normalizar contrato Router').first().json;
const rutas = [
  { set: 'Set contrato Billing', worker: 'worker1_billing_modulo4_acorsi_bruno' },
  { set: 'Set contrato Tech Support', worker: 'worker2_tech_support_modulo4_acorsi_bruno' },
  { set: 'Set contrato Sales', worker: 'worker3_sales_modulo4_acorsi_bruno' }
];
const ruta = rutas.find(r => $(r.set).isExecuted);
const enviado = ruta ? $(ruta.set).first().json : null;
const r = $json;
return [{ json: {
  timestamp: new Date().toISOString(),
  execution_id: $execution.id,
  session_id: src.session_id,
  original_input: src.original_input,
  intent: src.intent,
  confidence: src.confidence,
  risk: src.risk,
  worker: ruta ? ruta.worker : ($('Respuesta de bienvenida').isExecuted ? 'Bienvenida (sin delegar)' : 'HITL (supervisor humano)'),
  parametros_enviados: enviado ? JSON.stringify(enviado) : 'N/A: no se delegó a ningún worker',
  status: r.status ?? 'success',
  respuesta: r.respuesta ?? '',
  requires_human: Boolean(r.requires_human),
  error: r.error ?? null
} }];

const n = $('Normalizar contrato Router').first().json;
const c = $('Consolidar resultado').first().json;
const count = Number(n.contador_mensajes || 0) + 1;
const estado = c.requires_human ? 'ESCALADO_HUMANO' : (c.status === 'error' ? 'ERROR' : 'EN_CURSO');
return [{ json: {
  Session_ID: n.session_id,
  user_name: n.user_name,
  Estado_Caso: estado,
  Resumen_Consolidado: n.last_summary,
  Datos_Clave: n.datos_clave,
  contador_mensajes: count,
  Fecha_Actualizacion: new Date().toISOString()
} }];

